function extractTokens(usage) {
  if (!usage) return { tin: 0, tout: 0 };
  const tin =
    usage.prompt_tokens ||
    usage.input_tokens ||
    usage.promptTokens ||
    0;
  const tout =
    usage.completion_tokens ||
    usage.output_tokens ||
    usage.completionTokens ||
    0;
  return { tin: Number(tin) || 0, tout: Number(tout) || 0 };
}

function computeCost(model, usage) {
  const { tin, tout } = extractTokens(usage);

  // 1. Explicit free: model ID ends in :free OR it's in the FREE_MODELS allowlist
  if (/:free$/i.test(model || '') || FREE_MODELS.has(model)) {
    return { cost: 0, tin, tout };
  }

  // 2. Provider reported its own cost (OpenRouter does this sometimes)
  if (usage && typeof usage.total_cost === 'number') {
    return { cost: Number(usage.total_cost) || 0, tin, tout };
  }

  // 3. Fall back to our pricing table
  const p = PRICING[model];
  if (!p) return { cost: 0, tin, tout };

  const cost = (tin * p.in + tout * p.out) / 1_000_000;
  return { cost, tin, tout };
}

return { cost, tin, tout };
}

