.main {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 1rem;
  display: flex;
  flex-direction: column;
  gap: 1rem;
}

/* Status */
.status {
  font-weight: 600;
  text-align: center;
}

/* Video */
.videos {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
  justify-content: center;
}

.videos video {
  width: 100%;
  max-width: 360px;
  border-radius: var(--radius);
  background: #000;
  object-fit: cover;
